    "sociology/culture-and-norms": { title: "Маданият жана нормалар", desc: "Сен ойлонбой туруп кезекке турасың, китепканаларда үнүңдү басаңдатасың жана кийим эрежелерин бузганда ыңгайсыз сезесиң — бул маданияттын көрүнбөй иштеп жатканы." },
    "sociology/families-around-the-world": { title: "Дүйнө жүзүндөгү үй-бүлөлөр", desc: "Үй-бүлө жашоосу маданияттар арасында кандай айырмаланарын көрүү үчүн дүйнөнү кыдырыңыз." },
    "sociology/gender-inequality": { title: "Гендердик теңсиздик", desc: "Гендердик айлык айырманы жана «айнек шып» деп аталган тоскоолдукту изилдеңиз." },
