    "sociology/meads-i-and-me": { title: "Миддин «Мен» жана «Мени»", desc: "Джордж Герберт Мид адамдын «мен» түшүнүгү башка адамдар аркылуу кантип өсөрүн кандай көргөнүн билип алыңыз." },
    "sociology/nuclear-and-extended": { title: "Өзөктүк жана кеңейтилген үй-бүлөлөр", desc: "Бир үйдө жашаган кичинекей үй-бүлөлөрдү чоң үй-бүлө топтору менен салыштырыңыз." },
    "sociology/one-parent-and-blended": { title: "Бир ата-энелүү жана аралаш үй-бүлөлөр", desc: "Ата-энелер бөлөк жашаганда же кайра үйлөнгөндө үй-бүлөлөр кантип жаңы формага ээ болорун көрүңүз." },
